import * as React from "react";
import { Link } from "@tanstack/react-router";
import { ArrowRight, Check, Heart, LocateFixed, Mic, PawPrint, Sparkles } from "./bow-icons";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { priorityTone, type Priority } from "@/lib/bow-data";
import { cn } from "@/lib/utils";
import dogCardImage from "@/assets/bow-dog-card.jpg";
import storyCardImage from "@/assets/bow-story-card.jpg";

export function BowLogo({ light = false }: { light?: boolean }) {
  return <Link to="/" className={cn("flex items-center gap-3", light ? "text-primary-foreground" : "text-foreground")} aria-label="BOW home">
    <span className="relative grid h-10 w-10 place-items-center text-[0.68rem] font-semibold tracking-[0.16em]">
      <PawPrint className="absolute h-8 w-8 text-bow-brown" strokeWidth={1.7} />
    </span>
    <span className="leading-none"><strong className="font-display text-[2rem] font-normal tracking-[-0.03em]">BOW</strong><small className="mt-1 block text-[0.56rem] font-medium tracking-[0.14em] opacity-80">FOR EVERY STREET SOUL</small></span>
  </Link>;
}

export function SectionHeading({ eyebrow, title, body, action }: { eyebrow?: string; title: string; body?: string; action?: React.ReactNode }) {
  return <div className="flex flex-col gap-5 sm:flex-row sm:items-end sm:justify-between">
    <div className="max-w-2xl"><p className="eyebrow">{eyebrow}</p><h2 className="mt-3 font-display text-4xl leading-[0.98] tracking-[-0.035em] text-foreground sm:text-5xl">{title}</h2>{body && <p className="mt-4 max-w-xl text-sm leading-6 text-muted-foreground sm:text-base">{body}</p>}</div>
    {action}
  </div>;
}

export function ActionLink({ to, children, variant = "default" }: { to: string; children: React.ReactNode; variant?: "default" | "outline" }) {
  return <Button asChild variant={variant === "outline" ? "outline" : "default"} className="h-12 rounded-lg px-5 text-[0.78rem] tracking-[0.01em]"><Link to={to}>{children}<ArrowRight className="h-4 w-4" /></Link></Button>;
}

export function PageIntro({ eyebrow, title, body }: { eyebrow: string; title: string; body: string }) {
  return <section className="border-b border-border bg-bow-ivory px-5 pb-16 pt-16 sm:px-10 sm:pb-20 sm:pt-24"><div className="mx-auto max-w-7xl"><p className="eyebrow">{eyebrow}</p><h1 className="mt-4 max-w-4xl font-display text-5xl leading-[0.95] tracking-[-0.045em] text-foreground sm:text-7xl">{title}</h1><p className="mt-6 max-w-2xl text-base leading-7 text-muted-foreground sm:text-lg">{body}</p></div></section>;
}

export function PriorityBadge({ priority }: { priority: Priority }) {
  return <span className={cn("priority-badge", `priority-${priorityTone(priority)}`)}><span className="h-2 w-2 rounded-full bg-current" />{priority} Priority</span>;
}

export function BowCard({ children, className }: { children: React.ReactNode; className?: string }) {
  return <div className={cn("bow-card", className)}>{children}</div>;
}

export function ReportForm() {
  const [recording, setRecording] = React.useState(false);
  const [submitted, setSubmitted] = React.useState(false);
  return <BowCard className="p-5 sm:p-7"><div className="flex items-center justify-between"><div><p className="font-display text-2xl">Tell us what you see.</p><p className="mt-1 text-xs text-muted-foreground">Your report helps a human reach the right street soul.</p></div><span className="grid h-10 w-10 place-items-center rounded-full bg-bow-sand text-bow-forest"><PawPrint className="h-5 w-5" /></span></div>
    <div className="mt-6 grid gap-3 sm:grid-cols-2"><label className="upload-tile sm:col-span-2"><input type="file" accept="image/*,video/*" multiple className="sr-only" /><span className="grid h-10 w-10 place-items-center rounded-full bg-background"><Sparkles className="h-4 w-4 text-bow-brown" /></span><span><strong className="block text-sm">Upload photo or short video</strong><small className="text-xs text-muted-foreground">JPG, PNG or MP4 · multiple files welcome</small></span></label><label className="relative sm:col-span-2"><span className="field-label">Location</span><Input placeholder="Enter a landmark or use current location" className="h-12 rounded-lg bg-background pr-11" /><LocateFixed className="absolute right-4 top-9 h-4 w-4 text-bow-brown" /></label><label className="sm:col-span-2"><span className="field-label">What is happening?</span><Textarea placeholder="Tell us what you noticed..." className="min-h-24 rounded-lg bg-background" /></label></div>
    <div className="mt-4 flex items-center gap-3"><Button type="button" variant="outline" size="icon" aria-label={recording ? "Stop voice report" : "Record a voice report"} onClick={() => setRecording(!recording)} className={cn("h-11 w-11 rounded-full", recording && "border-bow-brown text-bow-brown")}><Mic className="h-4 w-4" /></Button><span className="text-xs text-muted-foreground">{recording ? "Listening... speak naturally" : "Add a voice report"}</span><Button type="button" className="ml-auto h-11 rounded-lg px-5 text-xs" onClick={() => setSubmitted(true)}>{submitted ? "Report received" : "Analyze with BOW AI"}<ArrowRight className="h-4 w-4" /></Button></div>
    {submitted && <p className="mt-4 rounded-lg bg-bow-sage px-4 py-3 text-xs text-bow-forest"><Check className="mr-2 inline h-4 w-4" />Demo report ready for human review. No medical diagnosis is made by BOW AI.</p>}
  </BowCard>;
}

export function AnalysisResult() {
  return <BowCard className="overflow-hidden"><div className="border-b border-border bg-bow-forest px-6 py-5 text-primary-foreground"><div className="flex items-start justify-between"><div><p className="text-[0.65rem] uppercase tracking-[0.18em] opacity-70">AI-assisted welfare assessment</p><h3 className="mt-2 font-display text-3xl">High priority</h3></div><span className="rounded-full border border-primary-foreground/20 px-3 py-1 text-[0.65rem] uppercase tracking-widest">87% confidence</span></div></div><div className="space-y-5 p-6"><p className="text-sm leading-6 text-muted-foreground">The uploaded image shows signals that may need timely human attention.</p><div className="space-y-3">{["Possible wound visible", "Abnormal posture observed", "Possible swelling"].map((item) => <div key={item} className="flex items-center gap-3 text-sm"><span className="grid h-6 w-6 place-items-center rounded-full bg-bow-sage text-bow-forest"><Check className="h-3.5 w-3.5" /></span>{item}</div>)}</div><div className="border-t border-border pt-4"><p className="text-xs font-semibold uppercase tracking-[0.14em] text-foreground">Why this priority?</p><p className="mt-2 text-xs leading-5 text-muted-foreground">Visible indicators were flagged for a rescue coordinator to review. BOW AI does not diagnose medical conditions.</p></div><Button variant="outline" className="w-full rounded-lg text-xs">Request human review<ArrowRight className="h-4 w-4" /></Button></div></BowCard>;
}

export function FormField({ label, placeholder }: { label: string; placeholder: string }) { return <label><span className="field-label">{label}</span><Input placeholder={placeholder} className="h-12 rounded-lg bg-background" /></label>; }

export function DogCard({ name, detail, match, index = 0 }: { name: string; detail: string; match: string; index?: number }) { return <BowCard className="group overflow-hidden p-0"><div className="relative aspect-[0.92] overflow-hidden bg-bow-sand"><img src={index % 2 === 0 ? dogCardImage : storyCardImage} alt={`${name}, an adoptable street dog`} className="h-full w-full object-cover transition-transform duration-700 group-hover:scale-105" loading="lazy" width={900} height={1000} /><button type="button" aria-label={`Support ${name}`} className="absolute right-3 top-3 grid h-9 w-9 place-items-center rounded-full bg-background/85 text-bow-brown backdrop-blur"><Heart className="h-4 w-4" /></button></div><div className="p-4"><div className="flex items-start justify-between gap-2"><div><h3 className="font-display text-2xl">{name}</h3><p className="mt-1 text-[0.68rem] text-muted-foreground">{detail}</p></div><span className="text-xs font-semibold text-bow-forest">{match}<small className="block font-normal text-muted-foreground">match</small></span></div><Button className="mt-5 h-10 w-full rounded-lg text-xs">Meet {name}<ArrowRight className="h-4 w-4" /></Button></div></BowCard>; }

import { useEffect, useState } from "react";
import { PawPrint } from "@/components/bow-icons";

const PAW_STEPS = [
  { left: "8%", top: "72%", rotate: "-18deg", delay: 0 },
  { left: "20%", top: "58%", rotate: "14deg", delay: 260 },
  { left: "32%", top: "70%", rotate: "-16deg", delay: 520 },
  { left: "44%", top: "56%", rotate: "16deg", delay: 780 },
  { left: "56%", top: "68%", rotate: "-14deg", delay: 1040 },
  { left: "68%", top: "54%", rotate: "14deg", delay: 1300 },
  { left: "80%", top: "64%", rotate: "-16deg", delay: 1560 },
];

export function WelcomeScreen() {
  const [phase, setPhase] = useState<"hidden" | "playing" | "leaving">("hidden");

  useEffect(() => {
    if (window.sessionStorage.getItem("bow-welcomed")) return;
    setPhase("playing");
    const leaveTimer = window.setTimeout(() => setPhase("leaving"), 2600);
    const doneTimer = window.setTimeout(() => {
      window.sessionStorage.setItem("bow-welcomed", "1");
      setPhase("hidden");
    }, 3200);
    return () => {
      window.clearTimeout(leaveTimer);
      window.clearTimeout(doneTimer);
    };
  }, []);

  if (phase === "hidden") return null;

  return (
    <div
      aria-hidden="true"
      className={`fixed inset-0 z-[100] flex items-center justify-center bg-bow-ivory ${
        phase === "leaving" ? "welcome-exit" : ""
      }`}
    >
      {PAW_STEPS.map((step, index) => (
        <PawPrint
          key={index}
          className="welcome-paw absolute h-8 w-8 text-bow-brown sm:h-10 sm:w-10"
          style={{ left: step.left, top: step.top, rotate: step.rotate, animationDelay: `${step.delay}ms` }}
        />
      ))}
      <div className="welcome-logo text-center">
        <p className="font-display text-6xl tracking-[-0.04em] text-bow-forest sm:text-7xl">BOW</p>
        <p className="mt-3 text-[0.65rem] font-semibold uppercase tracking-[0.28em] text-bow-brown">
          Every street soul deserves a second chance
        </p>
      </div>
    </div>
  );
}

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const badgeVariants = cva(
  "inline-flex items-center rounded-md border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground shadow hover:bg-primary/80",
        secondary:
          "border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
        destructive:
          "border-transparent bg-destructive text-destructive-foreground shadow hover:bg-destructive/80",
        outline: "text-foreground",
      },
    },
    defaultVariants: {
      variant: "default",
    },
  },
);

export interface BadgeProps
  extends React.HTMLAttributes<HTMLDivElement>, VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
  return <div className={cn(badgeVariants({ variant }), className)} {...props} />;
}

export { Badge, badgeVariants };

import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

const buttonVariants = cva(
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium cursor-pointer transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:pointer-events-none disabled:opacity-50 disabled:cursor-not-allowed [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        default: "bg-primary text-primary-foreground shadow hover:bg-primary/90",
        destructive: "bg-destructive text-destructive-foreground shadow-sm hover:bg-destructive/90",
        outline:
          "border border-input bg-background shadow-sm hover:bg-accent hover:text-accent-foreground",
        secondary: "bg-secondary text-secondary-foreground shadow-sm hover:bg-secondary/80",
        ghost: "hover:bg-accent hover:text-accent-foreground",
        link: "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-9 px-4 py-2",
        sm: "h-8 rounded-md px-3 text-xs",
        lg: "h-10 rounded-md px-8",
        icon: "h-9 w-9",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>, VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp className={cn(buttonVariants({ variant, size, className }))} ref={ref} {...props} />
    );
  },
);
Button.displayName = "Button";

export { Button, buttonVariants };

import * as React from "react";
import * as LabelPrimitive from "@radix-ui/react-label";
import { Slot } from "@radix-ui/react-slot";
import {
  Controller,
  FormProvider,
  useFormContext,
  type ControllerProps,
  type FieldPath,
  type FieldValues,
} from "react-hook-form";

import { cn } from "@/lib/utils";
import { Label } from "@/components/ui/label";

const Form = FormProvider;

type FormFieldContextValue<
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
> = {
  name: TName;
};

const FormFieldContext = React.createContext<FormFieldContextValue | null>(null);

const FormField = <
  TFieldValues extends FieldValues = FieldValues,
  TName extends FieldPath<TFieldValues> = FieldPath<TFieldValues>,
>({
  ...props
}: ControllerProps<TFieldValues, TName>) => {
  return (
    <FormFieldContext.Provider value={{ name: props.name }}>
      <Controller {...props} />
    </FormFieldContext.Provider>
  );
};

const useFormField = () => {
  const fieldContext = React.useContext(FormFieldContext);
  const itemContext = React.useContext(FormItemContext);
  const { getFieldState, formState } = useFormContext();

  if (!fieldContext) {
    throw new Error("useFormField should be used within <FormField>");
  }

  if (!itemContext) {
    throw new Error("useFormField should be used within <FormItem>");
  }

  const fieldState = getFieldState(fieldContext.name, formState);

  const { id } = itemContext;

  return {
    id,
    name: fieldContext.name,
    formItemId: `${id}-form-item`,
    formDescriptionId: `${id}-form-item-description`,
    formMessageId: `${id}-form-item-message`,
    ...fieldState,
  };
};

type FormItemContextValue = {
  id: string;
};

const FormItemContext = React.createContext<FormItemContextValue | null>(null);

const FormItem = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  ({ className, ...props }, ref) => {
    const id = React.useId();

    return (
      <FormItemContext.Provider value={{ id }}>
        <div ref={ref} className={cn("space-y-2", className)} {...props} />
      </FormItemContext.Provider>
    );
  },
);
FormItem.displayName = "FormItem";

const FormLabel = React.forwardRef<
  React.ElementRef<typeof LabelPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof LabelPrimitive.Root>
>(({ className, ...props }, ref) => {
  const { error, formItemId } = useFormField();

  return (
    <Label
      ref={ref}
      className={cn(error && "text-destructive", className)}
      htmlFor={formItemId}
      {...props}
    />
  );
});
FormLabel.displayName = "FormLabel";

const FormControl = React.forwardRef<
  React.ElementRef<typeof Slot>,
  React.ComponentPropsWithoutRef<typeof Slot>
>(({ ...props }, ref) => {
  const { error, formItemId, formDescriptionId, formMessageId } = useFormField();

  return (
    <Slot
      ref={ref}
      id={formItemId}
      aria-describedby={!error ? `${formDescriptionId}` : `${formDescriptionId} ${formMessageId}`}
      aria-invalid={!!error}
      {...props}
    />
  );
});
FormControl.displayName = "FormControl";

const FormDescription = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, ...props }, ref) => {
  const { formDescriptionId } = useFormField();

  return (
    <p
      ref={ref}
      id={formDescriptionId}
      className={cn("text-[0.8rem] text-muted-foreground", className)}
      {...props}
    />
  );
});
FormDescription.displayName = "FormDescription";

const FormMessage = React.forwardRef<
  HTMLParagraphElement,
  React.HTMLAttributes<HTMLParagraphElement>
>(({ className, children, ...props }, ref) => {
  const { error, formMessageId } = useFormField();
  const body = error ? String(error?.message ?? "") : children;

  if (!body) {
    return null;
  }

  return (
    <p
      ref={ref}
      id={formMessageId}
      className={cn("text-[0.8rem] font-medium text-destructive", className)}
      {...props}
    >
      {body}
    </p>
  );
});
FormMessage.displayName = "FormMessage";

export {
  useFormField,
  Form,
  FormItem,
  FormLabel,
  FormControl,
  FormDescription,
  FormMessage,
  FormField,
};

import * as React from "react";
import * as NavigationMenuPrimitive from "@radix-ui/react-navigation-menu";
import { cva } from "class-variance-authority";
import { ChevronDown } from "lucide-react";

import { cn } from "@/lib/utils";

const NavigationMenu = React.forwardRef<
  React.ElementRef<typeof NavigationMenuPrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof NavigationMenuPrimitive.Root>
>(({ className, children, ...props }, ref) => (
  <NavigationMenuPrimitive.Root
    ref={ref}
    className={cn("relative z-10 flex max-w-max flex-1 items-center justify-center", className)}
    {...props}
  >
    {children}
    <NavigationMenuViewport />
  </NavigationMenuPrimitive.Root>
));
NavigationMenu.displayName = NavigationMenuPrimitive.Root.displayName;

const NavigationMenuList = React.forwardRef<
  React.ElementRef<typeof NavigationMenuPrimitive.List>,
  React.ComponentPropsWithoutRef<typeof NavigationMenuPrimitive.List>
>(({ className, ...props }, ref) => (
  <NavigationMenuPrimitive.List
    ref={ref}
    className={cn("group flex flex-1 list-none items-center justify-center space-x-1", className)}
    {...props}
  />
));
NavigationMenuList.displayName = NavigationMenuPrimitive.List.displayName;

const NavigationMenuItem = NavigationMenuPrimitive.Item;

const navigationMenuTriggerStyle = cva(
