function Adopt() { return <main><PageIntro eyebrow="Adoption" title="A forever home starts with a good match." body="Meet street souls who are ready to be known for their personalities, not their past. Take a few thoughtful questions to see where your lifestyle may connect." /><section className="px-5 py-14 sm:px-10 sm:py-24"><div className="mx-auto max-w-7xl"><SectionHeading eyebrow="Find your companion" title="Dogs waiting to be known." action={<Button variant="outline" className="rounded-lg text-xs">Filter by location</Button>} /><div className="mt-10 grid grid-cols-2 gap-3 lg:grid-cols-4">{dogs.map((dog, index) => <DogCard key={dog.name} {...dog} index={index} />)}</div></div></section><section className="border-y border-border bg-bow-paper px-5 py-16 sm:px-10 sm:py-24"><div className="mx-auto grid max-w-7xl gap-8 lg:grid-cols-[0.8fr_1.2fr]"><div><p className="eyebrow">AI-assisted matching</p><h2 className="mt-3 font-display text-5xl leading-none">Let lifestyle lead the way.</h2><p className="mt-5 text-sm leading-6 text-muted-foreground">Answer a few questions about your home, time, experience, and activity level. BOW suggests where a conversation could begin — never guarantees an adoption outcome.</p></div><BowCard className="p-6 sm:p-8"><div className="grid gap-5 sm:grid-cols-2"><FormField label="Home type" placeholder="Apartment or house" /><FormField label="Family size" placeholder="Tell us about your household" /><FormField label="Time available" placeholder="A little / some / lots" /><FormField label="Preferred dog size" placeholder="Small / medium / any" /></div><Button className="mt-7 h-12 w-full rounded-lg bg-bow-forest text-primary-foreground">See my best matches<ArrowRight className="h-4 w-4" /></Button></BowCard></div></section><section className="px-5 py-16 sm:px-10 sm:py-24"><div className="mx-auto max-w-5xl"><SectionHeading eyebrow="Your best matches" title="A starting point for a meaningful hello." /><div className="mt-10 grid gap-3 sm:grid-cols-3">{dogs.slice(0, 3).map((dog, index) => <BowCard key={dog.name} className="p-6"><div className="flex items-start justify-between"><span className="font-display text-4xl">{dog.name}</span><span className="font-semibold text-bow-forest">{dog.match}</span></div><p className="mt-1 text-xs text-muted-foreground">compatibility recommendation</p><div className="mt-7 space-y-3 text-xs text-muted-foreground"><p><Check className="mr-2 inline h-4 w-4 text-bow-forest" />{dog.detail}</p><p><Check className="mr-2 inline h-4 w-4 text-bow-forest" />{dog.status}</p></div><Button variant="outline" className="mt-7 w-full rounded-lg text-xs">Meet {dog.name}<ArrowRight className="h-4 w-4" /></Button></BowCard>)}</div></div></section></main>; }

