import { createFileRoute } from "@tanstack/react-router";
import { ActionLink, BowCard, FormField, PageIntro, SectionHeading } from "@/components/bow-ui";
import { Check, Heart, ShieldCheck, Utensils } from "@/components/bow-icons";
import { Button } from "@/components/ui/button";
import { FoodBowl } from "@/components/bow-pet-animations";
export const Route = createFileRoute("/donate")({ head: () => ({ meta: [{ title: "Feed with Care — BOW" }, { name: "description", content: "Start a responsible feeding drive or share suitable food with nearby BOW initiatives." }, { property: "og:title", content: "Feed with Care — BOW" }, { property: "og:description", content: "A meal makes a difference when it is shared responsibly." }, { property: "og:type", content: "website" }, { name: "twitter:card", content: "summary_large_image" }] }), component: Donate });
function Donate() { return <main><PageIntro eyebrow="Food support" title="A meal makes a difference when it is shared responsibly." body="Create a feeding drive, offer suitable food, or help a nearby initiative reach more street souls. BOW keeps practical guidance close to every action." /><section className="px-5 py-14 sm:px-10 sm:py-24"><div className="mx-auto grid max-w-7xl gap-8 lg:grid-cols-[0.85fr_1.15fr]"><div><SectionHeading eyebrow="Celebrate with BOW" title="Turn a special day into a shared meal." body="Invite contributors, choose a location, and make your celebration count for a neighborhood." /><div className="mt-8"><ActionLink to="/community">See feeding stories</ActionLink></div><FoodBowl className="mt-12" /></div><BowCard className="p-6 sm:p-8"><div className="grid gap-5 sm:grid-cols-2"><FormField label="Number of dogs" placeholder="20" /><FormField label="Location" placeholder="Choose a feeding point" /><FormField label="Date" placeholder="Select a date" /><FormField label="Contributors" placeholder="Optional" /></div><Button className="mt-7 h-12 w-full rounded-lg bg-bow-forest text-primary-foreground">Create feeding drive</Button></BowCard></div></section><section className="border-y border-border bg-bow-sand/35 px-5 py-16 sm:px-10 sm:py-24"><div className="mx-auto max-w-7xl"><SectionHeading eyebrow="Nearby initiatives" title="Food is already moving nearby." body="Demo locations show how BOW can recommend where a suitable contribution may help most." /><div className="mt-10 grid gap-3 md:grid-cols-3">{[["Feeding Point C", "18 dogs", "Recommended"], ["Feeding Point A", "11 dogs", "2.4 km away"], ["Feeding Point D", "7 dogs", "4.8 km away"]].map(([name, count, note], index) => <BowCard key={name} className={index === 0 ? "border-bow-forest bg-bow-forest text-primary-foreground" : "p-6"}><div className="flex items-start justify-between"><Utensils className={index === 0 ? "h-5 w-5 text-bow-gold" : "h-5 w-5 text-bow-brown"} /><span className="text-xs opacity-70">{note}</span></div><h3 className="mt-8 font-display text-3xl">{name}</h3><p className="mt-2 text-sm opacity-70">Currently supporting {count}.</p></BowCard>)}</div></div></section><section className="px-5 py-16 sm:px-10 sm:py-24"><div className="mx-auto grid max-w-7xl gap-8 md:grid-cols-2"><BowCard className="p-7"><ShieldCheck className="h-6 w-6 text-bow-forest" /><h2 className="mt-6 font-display text-3xl">Responsible-food guidelines</h2><ul className="mt-5 space-y-3 text-sm leading-6 text-muted-foreground">{["Share fresh, suitable food only.", "Avoid foods known to be harmful to dogs.", "Keep water, hygiene, and local context in mind.", "When unsure, ask a veterinary professional."] .map((item) => <li key={item}><Check className="mr-2 inline h-4 w-4 text-bow-forest" />{item}</li>)}</ul></BowCard><BowCard className="bg-bow-forest p-7 text-primary-foreground"><Heart className="h-6 w-6 text-bow-gold" /><h2 className="mt-6 font-display text-3xl">Help a team keep showing up.</h2><p className="mt-4 text-sm leading-6 text-primary-foreground/70">Financial support, volunteering, and local knowledge all make the response stronger.</p><div className="mt-7"><Button variant="outline" className="rounded-lg">Partner with BOW</Button></div></BowCard></div></section></main>; }

