import { createFileRoute } from "@tanstack/react-router";
import { cases, priorityTone } from "@/lib/bow-data";
import { ArrowRight, BarChart3, Check, ChevronRight, MessageCircle, ShieldCheck } from "@/components/bow-icons";
import { BowCard, PageIntro, PriorityBadge, SectionHeading } from "@/components/bow-ui";
import { Button } from "@/components/ui/button";
export const Route = createFileRoute("/rescue")({ head: () => ({ meta: [{ title: "Rescue Command Center — BOW" }, { name: "description", content: "A decision-support dashboard for rescue teams coordinating street-dog welfare cases." }, { property: "og:title", content: "Rescue Command Center — BOW" }, { property: "og:description", content: "Prioritize human attention with clear case context." }, { property: "og:type", content: "website" }, { name: "twitter:card", content: "summary_large_image" }] }), component: Rescue });
function Rescue() { return <main><PageIntro eyebrow="For rescue organizations" title="A calmer command center for urgent work." body="See the cases that need attention, understand their context, and coordinate the next human action without losing sight of the bigger picture." /><section className="px-5 py-14 sm:px-10 sm:py-24"><div className="mx-auto max-w-7xl"><div className="grid grid-cols-3 gap-3"><Stat label="High" value="06" tone="high" /><Stat label="Medium" value="11" tone="medium" /><Stat label="Low" value="07" tone="low" /></div><div className="mt-10 grid gap-8 lg:grid-cols-[1.35fr_0.65fr]"><BowCard className="overflow-hidden"><div className="flex flex-col gap-3 border-b border-border p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="eyebrow">Live case queue</p><h2 className="mt-2 font-display text-3xl">Active welfare cases</h2></div><Button variant="outline" className="rounded-lg text-xs">Export view<ArrowRight className="h-4 w-4" /></Button></div><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-bow-sand/50 text-[0.63rem] uppercase tracking-[0.15em] text-muted-foreground"><tr><th className="px-5 py-3 font-medium">Case</th><th className="px-5 py-3 font-medium">Location</th><th className="px-5 py-3 font-medium">Priority</th><th className="px-5 py-3 font-medium">Team</th><th className="px-5 py-3 font-medium">Status</th></tr></thead><tbody>{cases.map((item) => <tr key={item.id} className="border-t border-border"><td className="px-5 py-4 font-semibold">{item.id}<span className="mt-1 block text-xs font-normal text-muted-foreground">{item.time}</span></td><td className="px-5 py-4 text-xs text-muted-foreground">{item.location}<span className="mt-1 block text-[0.68rem] text-foreground">{item.indicator}</span></td><td className="px-5 py-4"><PriorityBadge priority={item.priority} /></td><td className="px-5 py-4 text-xs">{item.team}</td><td className="px-5 py-4 text-xs text-muted-foreground">{item.status}</td></tr>)}</tbody></table></div></BowCard><div className="space-y-8"><BowCard className="bg-bow-forest p-6 text-primary-foreground"><p className="text-[0.62rem] uppercase tracking-[0.16em] text-bow-gold">Recommended case</p><h3 className="mt-4 font-display text-3xl">PC-1047</h3><PriorityBadge priority="High" /><p className="mt-4 text-sm text-primary-foreground/70">1.2 km away · reported 18 minutes ago</p><div className="mt-5 border-t border-primary-foreground/15 pt-4 text-xs"><span className="text-primary-foreground/60">Recommended team</span><strong className="mt-1 block text-sm">Team A · available</strong></div><p className="mt-5 text-[0.68rem] leading-5 text-primary-foreground/60">Decision support only. Distance, urgency, and team availability are presented as a starting point for human coordination.</p></BowCard><BowCard className="p-6"><div className="flex items-center gap-3"><span className="grid h-10 w-10 place-items-center rounded-full bg-bow-sage text-bow-forest"><MessageCircle className="h-4 w-4" /></span><div><p className="font-display text-2xl">Ask BOW</p><p className="text-xs text-muted-foreground">Try a question about this queue</p></div></div><div className="mt-5 grid gap-2">{["High-priority cases within 5 km?", "Which cases wait over 24 hours?", "How many were resolved this week?"] .map((question) => <button type="button" key={question} className="flex items-center justify-between rounded-lg border border-border px-3 py-3 text-left text-xs transition-colors hover:bg-bow-sand">{question}<ChevronRight className="h-4 w-4 text-bow-brown" /></button>)}</div></BowCard></div></div></div></section><section className="bg-bow-paper px-5 py-16 sm:px-10 sm:py-24"><div className="mx-auto max-w-7xl"><SectionHeading eyebrow="Case workflow" title="Every case has a next step." /><div className="mt-10 grid gap-2 sm:grid-cols-6">{["Reported", "Reviewed", "Assigned", "Intervention", "Follow-up", "Resolved"].map((step, i) => <div key={step} className="relative border border-border bg-background p-4"><span className="text-xs text-bow-brown">0{i + 1}</span><p className="mt-4 text-sm font-semibold">{step}</p>{i < 5 && <ChevronRight className="absolute -right-3 top-1/2 z-10 hidden h-5 w-5 -translate-y-1/2 bg-bow-paper text-bow-brown sm:block" />}</div>)}</div></div></section></main>; }
function Stat({ label, value, tone }: { label: string; value: string; tone: string }) { return <BowCard className={`p-4 sm:p-6 ${tone === "high" ? "border-red-200" : tone === "medium" ? "border-amber-200" : "border-bow-sage"}`}><p className="text-[0.65rem] uppercase tracking-[0.14em] text-muted-foreground">{label} priority</p><p className="mt-3 font-display text-4xl">{value}</p></BowCard>; }
